import{Swarm,defaults,problems,handCheck}from'./engine.js';
const $=id=>document.getElementById(id),fmt=n=>Math.abs(n)<.0001&&n!==0?n.toExponential(2):n.toFixed(4),vec=a=>'('+a.map(n=>n.toFixed(3)).join(', ')+')';
let sim=new Swarm(),selected=0,timer=null,records=[],cursor=0,heat=null;
function snapshot(){return JSON.parse(JSON.stringify({iteration:sim.iteration,phase:sim.phase,steps:sim.steps,particles:sim.particles,best:sim.best,bestScore:sim.bestScore,bestId:sim.bestId,history:sim.history}))}
function save(){records.push(snapshot());cursor=records.length-1}
function pause(){if(timer)clearInterval(timer);timer=null;$('play').innerHTML='▶ <span>Play</span>'}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),3000)}
function fresh(config){pause();sim=new Swarm(config);selected=0;records=[];save();$('particle-select').innerHTML=sim.particles.map(p=>`<option value="${p.id}">Particle ${String(p.id+1).padStart(2,'0')}</option>`).join('');heat=null;render()}
function step(){if(cursor<records.length-1){cursor++;render();return}if(sim.step()){save();render()}else pause();if(sim.iteration>=sim.c.limit)pause()}
function start(){if(timer){pause();return}if(cursor===records.length-1&&sim.iteration>=sim.c.limit){toast('Experiment complete. Reset to run again.');return}$('play').innerHTML='Ⅱ <span>Pause</span>';timer=setInterval(step,Number($('speed').value))}
function state(){return records[cursor]}
const titles=['UPDATE THE BESTS','CALCULATE VELOCITY','MOVE THE PARTICLES','EVALUATE FITNESS'];
function render(){const s=state(),p=s.particles[selected],problem=sim.problem;$('iteration').innerHTML=String(s.iteration).padStart(2,'0')+` <small>/ ${sim.c.limit}</small>`;$('best-score').textContent=fmt(s.bestScore);const optimum=sim.c.problem==='rosenbrock'?[1,1]:[0,0];$('distance').textContent=Math.hypot(...s.best.map((x,d)=>x-optimum[d])).toFixed(4);$('landscape-name').textContent=problem.name+' landscape';$('formula').textContent=problem.formula;$('problem-tip').textContent=problems[$('problem').value].tip;$('status').textContent=s.iteration>=sim.c.limit?'Experiment complete':s.steps===0?'Ready to explore':`Iteration ${s.iteration+1} · ${['Memory updated','Velocity calculated','Particles moved','Fitness evaluated'][s.phase]}`;$('phase-title').textContent=s.steps===0?'LET’S BEGIN':titles[s.phase];document.querySelectorAll('.phases li').forEach(li=>li.classList.toggle('active',s.steps>0&&Number(li.dataset.phase)===s.phase));
 const explanation=s.steps===0?`${sim.c.count} particles are scattered across the landscape. Each remembers its starting point. Press Step to see how they decide where to go.`:s.phase===1?'Each particle combines momentum, a pull toward its own best point, and a pull toward the swarm’s best point. The arrows show these three influences for your selected particle.':s.phase===2?'The particles add their new velocity to their position. Their memories have not changed yet. At an edge, the position is clamped and that velocity component stops.':s.phase===3?'We plug each new position into the objective function. A smaller value means a better candidate. The fitness column now reflects the new positions.':`${s.particles.filter(q=>q.improved).length} particles improved their personal best. The swarm shares the best remembered discovery: ${fmt(s.bestScore)}.${s.iteration>=sim.c.limit?' The iteration budget is reached; this does not guarantee the true optimum.':' A new iteration can now begin.'}`;$('explanation').textContent=explanation;
 $('particle-select').value=selected;$('particle-position').textContent=`Position ${vec(p.x)} · ${s.phase===2?'fitness pending evaluation':`fitness ${fmt(p.score)}`}`;for(const key of['inertia','personal','social'])$('force-'+key).textContent=p.detail?vec(p.detail[key]):'—';$('force-total').textContent=p.detail?vec(p.detail.used):'—';$('force-note').textContent=!p.detail?'Step once to reveal the forces acting on this particle.':`${p.detail.clipped?'Speed limit applied: each component is capped at '+(problem.bounds*.4).toFixed(3)+'. ':''}${p.detail.boundary?'An edge was reached; the affected velocity component was set to zero. ':''}Force vectors are from the last velocity calculation.`;
 $('arithmetic').innerHTML=p.detail?['x','y'].map((axis,d)=>`<b>${axis} coordinate</b><br>r₁ = ${p.detail.r1[d].toFixed(4)}, r₂ = ${p.detail.r2[d].toFixed(4)}<br>${sim.c.w} × ${p.detail.oldV[d].toFixed(4)}<br>+ ${sim.c.c1} × ${p.detail.r1[d].toFixed(4)} × (${p.detail.pbest[d].toFixed(4)} − ${p.detail.from[d].toFixed(4)})<br>+ ${sim.c.c2} × ${p.detail.r2[d].toFixed(4)} × (${p.detail.gbest[d].toFixed(4)} − ${p.detail.from[d].toFixed(4)})<br>= ${p.detail.raw[d].toFixed(4)} before speed limit<br>`).join('<br>'):'Press Step to generate the first calculation.';
 $('population').innerHTML=s.particles.map(q=>`<tr class="${q.id===selected?'selected-row':''}"><td><button data-particle="${q.id}" aria-label="Inspect particle ${q.id+1}">${String(q.id+1).padStart(2,'0')}${q.id===s.bestId?' ✧':''}</button></td><td>${fmt(q.x[0])}</td><td>${fmt(q.x[1])}</td><td>${fmt(q.v[0])}</td><td>${fmt(q.v[1])}</td><td>${s.phase===2?'Pending':fmt(q.score)}</td><td>${fmt(q.bestScore)}</td></tr>`).join('');$('timeline').max=records.length-1;$('timeline').value=cursor;$('step-count').textContent=`Phase ${s.steps}`;$('back').disabled=cursor===0;$('step').disabled=cursor===records.length-1&&s.iteration>=sim.c.limit;$('reset').disabled=s.steps===0&&records.length===1;draw();chart();}
function draw(){const canvas=$('plot'),ctx=canvas.getContext('2d'),W=900,H=560,pad={l:46,r:22,t:20,b:35},pw=W-pad.l-pad.r,ph=H-pad.t-pad.b,b=sim.problem.bounds,s=state(),point=v=>[pad.l+(v[0]+b)/(2*b)*pw,pad.t+(b-v[1])/(2*b)*ph];ctx.clearRect(0,0,W,H);
 if(!heat){heat=document.createElement('canvas');heat.width=280;heat.height=180;const h=heat.getContext('2d'),data=h.createImageData(280,180),max=sim.problem.fn(b,b),scale=sim.c.problem==='rastrigin'?65:sim.c.problem==='rosenbrock'?Math.log1p(max):Math.log1p(2*b*b);for(let y=0;y<180;y++)for(let x=0;x<280;x++){const value=sim.problem.fn(-b+x/279*2*b,b-y/179*2*b),t=Math.min(1,sim.c.problem==='rastrigin'?value/scale:Math.log1p(value)/scale),band=Math.floor(t*14)/14,k=(y*280+x)*4,lo=[249,250,255],hi=[112,109,187];for(let d=0;d<3;d++)data.data[k+d]=lo[d]+(hi[d]-lo[d])*band*.76;data.data[k+3]=255}h.putImageData(data,0,0)}
 ctx.drawImage(heat,pad.l,pad.t,pw,ph);ctx.strokeStyle='#ffffff55';ctx.lineWidth=1;ctx.font='16px DM Sans, sans-serif';ctx.fillStyle='#8b8fa7';ctx.textAlign='center';for(let i=0;i<=4;i++){let x=pad.l+pw*i/4,y=pad.t+ph*i/4;ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,pad.t+ph);ctx.moveTo(pad.l,y);ctx.lineTo(pad.l+pw,y);ctx.stroke();ctx.fillText((-b+2*b*i/4).toFixed(1),x,H-8);ctx.textAlign='right';ctx.fillText((b-2*b*i/4).toFixed(1),pad.l-10,y+5);ctx.textAlign='center'}
 const opt=point(sim.c.problem==='rosenbrock'?[1,1]:[0,0]);ctx.strokeStyle='#8990a6';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(...opt,12,0,Math.PI*2);ctx.moveTo(opt[0]-18,opt[1]);ctx.lineTo(opt[0]+18,opt[1]);ctx.moveTo(opt[0],opt[1]-18);ctx.lineTo(opt[0],opt[1]+18);ctx.stroke();
 if($('trails').checked){for(const p of s.particles){ctx.strokeStyle=p.id===selected?'#e89a6866':'#7886cc35';ctx.lineWidth=p.id===selected?2:1;ctx.beginPath();p.trail.forEach((v,i)=>{const q=point(v);i?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.stroke()}}
 for(const p of s.particles){const q=point(p.x);ctx.beginPath();ctx.arc(...q,p.id===selected?8:5.5,0,Math.PI*2);ctx.fillStyle=p.id===selected?'#ee9860':'#6d7dcc';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke();if(p.id===selected){ctx.beginPath();ctx.arc(...q,15,0,Math.PI*2);ctx.strokeStyle='#ee986066';ctx.stroke();ctx.fillStyle='#9b673f';ctx.font='bold 16px DM Sans';ctx.fillText('P'+String(p.id+1).padStart(2,'0'),q[0],q[1]-23)}}
 const p=s.particles[selected];if(p.detail){const origin=p.detail.from;function arrow(v,color){const a=point(origin),z=point(origin.map((x,d)=>x+v[d])),ang=Math.atan2(z[1]-a[1],z[0]-a[0]);if(Math.hypot(z[0]-a[0],z[1]-a[1])<2)return;ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...z);ctx.stroke();ctx.beginPath();ctx.moveTo(...z);ctx.lineTo(z[0]-10*Math.cos(ang-.45),z[1]-10*Math.sin(ang-.45));ctx.lineTo(z[0]-10*Math.cos(ang+.45),z[1]-10*Math.sin(ang+.45));ctx.fill()}ctx.save();ctx.beginPath();ctx.rect(pad.l,pad.t,pw,ph);ctx.clip();arrow(p.detail.inertia,'#e39455');arrow(p.detail.personal,'#a36ac4');arrow(p.detail.social,'#5265df');ctx.restore()}
 const best=point(s.best);ctx.fillStyle='#384dc8';ctx.strokeStyle='white';ctx.lineWidth=3;ctx.font='bold 30px sans-serif';ctx.strokeText('✧',best[0],best[1]+10);ctx.fillText('✧',best[0],best[1]+10);
}
function chart(){const s=state(),h=s.history,logs=h.map(v=>Math.log10(Math.max(v,1e-12))),hi=Math.max(...logs),lo=Math.min(...logs),span=Math.max(hi-lo,.5),coords=logs.map((v,i)=>[12+i/Math.max(sim.c.limit,1)*675,12+(hi-v)/span*85]),path=coords.map((q,i)=>(i?'L':'M')+q.join(',')).join(' ');$('chart').innerHTML=`<path d="M12,12H687 M12,55H687 M12,97H687" stroke="#eef0f5" fill="none"/><path d="${path} L${coords.at(-1)[0]},108 L12,108Z" fill="#eef0fe"/><path d="${path}" stroke="#6275dd" stroke-width="2.5" fill="none"/><circle cx="${coords.at(-1)[0]}" cy="${coords.at(-1)[1]}" r="4" fill="#5265df"/>`;$('chart-end').textContent='Iteration '+s.iteration;$('chart-insight').textContent=s.iteration?`${((1-s.bestScore/h[0])*100).toFixed(1)}% better than the start`:'Every discovery starts somewhere.'}
function verify(){const r=handCheck(),names={inertia:'w × v',personal:'c₁ r₁ (p − x)',social:'c₂ r₂ (g − x)',velocity:'New velocity v′',position:'New position x′',fitness:'Fitness f(x′)'};$('check-status').textContent=r.pass?'6 / 6 checks passed':'Check failed';$('checks').innerHTML=r.checks.map(c=>`<tr><td>${names[c.key]}</td><td>${Array.isArray(c.expected)?vec(c.expected):c.expected.toFixed(4)}</td><td>${Array.isArray(c.actual)?vec(c.actual):c.actual.toFixed(4)}</td><td class="check-pass">${c.pass?'✓ Pass':'✕ Fail'}</td></tr>`).join('')}
function tab(name){pause();document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==name);document.querySelectorAll('.nav').forEach(n=>{n.classList.toggle('active',n.dataset.tab===name);n.setAttribute('aria-current',n.dataset.tab===name?'page':'false')});history.replaceState(null,'','#'+name);if(name==='verify')verify();if(name==='lab')draw();window.scrollTo(0,0)}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>tab(b.dataset.tab)));document.querySelector('.brand').onclick=e=>{e.preventDefault();tab('lab')};
for(const key of['count','w','c1','c2'])$(key).addEventListener('input',()=>{$(key+'-out').textContent=key==='count'?$(key).value:Number($(key).value).toFixed(2)});
function readConfig(){const c={problem:$('problem').value};for(const key of['count','w','c1','c2','seed','limit']){const el=$(key),n=Number(el.value);if(el.value===''||!Number.isFinite(n)||n<Number(el.min)||n>Number(el.max)||((key==='seed'||key==='limit'||key==='count')&&!Number.isInteger(n))){el.reportValidity();el.focus();toast('Please enter a valid '+(key==='limit'?'iteration budget':key)+'.');return null}c[key]=n}return c}
$('apply').onclick=()=>{const c=readConfig();if(c){fresh(c);toast('New experiment ready. Press Play or Step.')}};$('problem').onchange=()=>{$('problem-tip').textContent=problems[$('problem').value].tip;toast('Landscape selected. Start a new experiment to apply it.')};$('play').onclick=start;$('step').onclick=()=>{pause();step()};$('reset').onclick=()=>fresh(sim.c);$('back').onclick=()=>{pause();cursor=Math.max(0,cursor-1);render()};$('speed').onchange=()=>{if(timer){pause();start()}};$('timeline').oninput=()=>{pause();cursor=Number($('timeline').value);render()};$('trails').onchange=draw;$('particle-select').onchange=()=>{selected=Number($('particle-select').value);render()};$('population').onclick=e=>{const button=e.target.closest('[data-particle]');if(button){selected=Number(button.dataset.particle);render()}};
$('plot').onclick=e=>{const r=e.currentTarget.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*900,y=(e.clientY-r.top)/r.height*560,b=sim.problem.bounds;const nearest=state().particles.map(p=>({id:p.id,d:Math.hypot(46+(p.x[0]+b)/(2*b)*832-x,20+(b-p.x[1])/(2*b)*505-y)})).sort((a,b)=>a.d-b.d)[0];if(nearest.d<35){selected=nearest.id;render()}};
$('try-social').onclick=()=>{$('c2').value=0;$('c2-out').textContent='0.00';const c=readConfig();if(c){fresh(c);toast('Social pull is off. Watch how the swarm behaves.')}};$('recheck').onclick=()=>{verify();toast('All six calculations independently matched within 10⁻¹⁰.')};$('export').onclick=()=>{const data={format:'swarm-lab-v1',config:sim.c,phaseNames:['updated memories','calculated velocities','moved positions','evaluated fitness'],note:'At phase 2 current fitness is stale until phase 3. Replay records include exact random factors.',frames:records.slice(0,cursor+1)},blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`swarm-lab-${sim.c.problem}-seed-${sim.c.seed}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Run exported with parameters and every completed phase.')};
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA','BUTTON','SUMMARY','A'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();if(!$('lab').hidden)start()}if(e.key==='ArrowRight'&&!$('lab').hidden){pause();step()}});
save();fresh(defaults);verify();if(['verify','guide'].includes(location.hash.slice(1)))tab(location.hash.slice(1));
